            if i > 0 and i + 2 < n and text[i] == ":" and text[i - 1].isdigit() and text[i + 1].isdigit() and text[i + 2].isdigit():
                if not (i + 3 < n and text[i + 3] == ":") and not (i - 3 >= 0 and text[i - 3] == ":"):
