            hour = int(hour_text)
            minute = int(minute_text[:2])
        elif text.isdigit():
            if len(text) <= 2:
                hour = int(text)
                minute = 0
            else:
                hour = int(text[:-2])
                minute = int(text[-2:])
        else:
            raise ValueError
        if am or pm:
            if hour == 12:
                hour = 0
            if pm:
                hour += 12
        return hour * 60 + minute

    def parse_hours(value):
        if value is None:
            return None
        if isinstance(value, dict):
            if "working_hours" in value:
                value = value["working_hours"]
            elif "start" in value and "end" in value:
                try:
                    start = parse_time(value["start"])
                    end = parse_time(value["end"])
                    if start < 0:
                        start = 0
                    if end < 0:
                        end = 0
                    if start > 24 * 60:
                        start = 24 * 60
                    if end > 24 * 60:
                        end = 24 * 60
                    if end > start:
                        return (start, end)
                except Exception:
                    return None
                return None
        if isinstance(value, list) or isinstance(value, tuple):
            if len(value) >= 2:
                try:
                    start = parse_time(value[0])
                    end = parse_time(value[1])
                    if start < 0:
                        start = 0
                    if end < 0:
