            return None
        if start < 0:
            start = 0
        if end < 0:
            end = 0
        if start > 24 * 60:
            start = 24 * 60
        if end > 24 * 60:
            end = 24 * 60
        if end > start:
            return (start, end)
        return None

    def get_day_data(cal, day):
        if isinstance(cal, dict):
            rows = cal.get("days")
            if isinstance(rows, list):
                for row in rows:
                    if isinstance(row, dict) and str(row.get("day", "")).lower() == day.lower():
