            return cal
        if isinstance(cal, list):
            for item in cal:
                if isinstance(item, dict) and str(item.get("day", "")).lower() == day.lower():
                    return item
            return cal
        return cal

    def find_times(text):
        times = []
        n = len(text)
        i = 0
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n:
                    ch = text[j]
                    if ch.isdigit() or ch == ":" or ch == " " or ch == "a" or ch == "A" or ch == "p" or ch == "P" or ch == "m" or ch == "M":
