                    busy.append((s, e))
            return

        if isinstance(cal, list) or isinstance(cal, tuple):
            for item in cal:
                scan_calendar(item, day_key, busy, work_window)
            return

        if isinstance(cal, str):
            bounds = event_bounds(cal)
            if bounds is not None:
                s = bounds[0]
                e = bounds[1]
                if e > s:
                    busy.append((s, e))

    people = [""]
    for name in attendees:
        people.append(name)

    start_results = {}

    if earliest != "":
        try:
            start_limit = parse_time(earliest)
        except Exception:
            start_limit = 0
        if start_limit < 0:
            start_limit = 0
        if start_limit > 24 * 60:
            start_limit = 24 * 60
        start_limit = ((start_limit + 14) // 15) * 15
    else:
        start_limit = 0

    if latest_end != "":
        try:
            end_limit = parse_time(latest_end)
        except Exception:
            end_limit = 24 * 60
        if end_limit < 0:
            end_limit = 0
        if end_limit > 24 * 60:
            end_limit = 24 * 60
    else:
        end_limit = 24 * 60

    for day in days:
        busy = []
        work_window = [0, 24 * 60]

        for person in people:
            cal = api.read_calendar(person, day)
            scan_calendar(cal, day, busy, work_window)

        if work_window[1] <= work_window[0]:
            continue

        if start_limit > work_window[0]:
            day_start = start_limit
        else:
            day_start = work_window[0]
        day_start = ((day_start + 14) // 15) * 15

        day_end = end_limit
        if work_window[1] < day_end:
            day_end = work_window[1]

        upper = day_end - minutes
        upper = (upper // 15) * 15
        if upper < day_start:
            continue

        if len(busy) > 0:
            clipped = []
            for s, e in busy:
                if e <= work_window[0] or s >= work_window[1]:
                    continue
                if s < work_window[0]:
                    s = work_window[0]
                if e > work_window[1]:
                    e = work_window[1]
                if e > s:
                    clipped.append((s, e))
            if len(clipped) > 0:
                clipped = sorted(clipped)
                merged = [list(clipped[0])]
                for s, e in clipped[1:]:
                    if s <= merged[-1][1]:
                        if e > merged[-1][1]:
                            merged[-1][1] = e
                    else:
                        merged.append([s, e])
            else:
                merged = []
        else:
            merged = []

        slots = []
        current = day_start
        while current <= upper:
            meeting_end = current + minutes
            free = True
            for s, e in merged:
                if s >= meeting_end:
                    break
                if e > current and s < meeting_end:
                    free = False
                    break
            if free:
                slots.append(format_time(current))
            current += 15

        if len(slots) > 0:
            start_results[day] = slots

    return {"starts": start_results}
